use std::time::Duration;

/// How often a failed request is tried again before its error is returned.
const MAX_TRIES: u32 = 3;

/// The wait before the first retry. Each further retry waits twice as long.
const FIRST_WAIT: Duration = Duration::from_millis(100);

pub fn fetch(url: &str) -> Result<Response, FetchError> {
    let mut wait = FIRST_WAIT;
    let mut last = None;
    for _ in 0..MAX_TRIES {
        match get(url) {
            Ok(response) => return Ok(response),
            Err(error) if error.is_temporary() => {
                std::thread::sleep(wait);
                wait *= 2;
                last = Some(error);
            }
            Err(error) => return Err(error),
        }
    }
    Err(last.expect("the loop ran at least once"))
}

/// The options of the fetcher, read from the command line.
#[derive(Debug, Parser)]
pub struct Options {
    /// The address to fetch.
    pub url: String,

    /// How long a single try may take, in seconds.
    #[arg(long, default_value_t = 10)]
    pub timeout: u64,

    /// Where the response body is written; standard output without it.
    #[arg(long)]
    pub output: Option<PathBuf>,

    /// Follow redirects, up to this many.
    #[arg(long, default_value_t = 5)]
    pub redirects: u32,

    /// Headers to send, as `Name: value`, one flag for each.
    #[arg(long = "header")]
    pub headers: Vec<String>,

    /// Print the status line and the headers before the body.
    #[arg(long)]
    pub include: bool,

    /// Print nothing but the body.
    #[arg(long, conflicts_with = "include")]
    pub silent: bool,

    /// The proxy to send the request through.
    #[arg(long)]
    pub proxy: Option<String>,

    /// Accept certificates that do not verify.
    #[arg(long)]
    pub insecure: bool,

    /// How many times a failed request is tried again.
    /// TODO: the flag has no name yet.
    pub tries: u32,
}

impl Options {
    pub fn timeout(&self) -> Duration {
        Duration::from_secs(self.timeout)
    }

    pub fn headers(&self) -> Result<Vec<(String, String)>, OptionsError> {
        self.headers
            .iter()
            .map(|header| {
                header
                    .split_once(':')
                    .map(|(name, value)| (name.trim().to_owned(), value.trim().to_owned()))
                    .ok_or_else(|| OptionsError::Header(header.clone()))
            })
            .collect()
    }
}
